import type { IoMappedChannel, IoMappingResponse } from "@pantin/protocol";
import { CANONICAL_ORDER_NOTE, describeIoProblem, readFolderIo } from "./io-folder.ts";
import { readFolderDocument } from "./validate-folder.ts";

// `pantin gvl <folder>` (ADR 0045 point 9, ADR 0049 point 9): the CODESYS
// global variable list of a valid mapping, modules in the order of io.json and
// channels in canonical order. No AT addresses: CODESYS assigns %I/%Q
// addresses in the device tree, where the channels are mapped to these
// variables.

const HEADER = [
  '// Generated by "pantin gvl" from io.json: do not edit it,',
  "// change the mapping and generate it again.",
  "//",
  "// WARNING (ADR 0046 point 10): a PLC trusts Pantin's feedback. The PLC under",
  "// test must never drive live outputs at the same time: use a SoftPLC, or a",
  "// controller with its field I/O disconnected.",
];

function declaration(moduleKey: string, channel: IoMappedChannel): string {
  return `  ${channel.variable} : ${channel.ioType}; // ${moduleKey} ${channel.zone} ${channel.address}, ${channel.tag}`;
}

function moduleDeclarations(module: IoMappingResponse["modules"][number]): string[] {
  return module.channels.map((channel) => declaration(module.key, channel));
}

/** The text of the GVL for the modules of a valid mapping. */
function renderGvl(modules: IoMappingResponse["modules"]): string {
  return [...HEADER, "VAR_GLOBAL", ...modules.flatMap(moduleDeclarations), "END_VAR", ""].join(
    "\n",
  );
}

export type GvlResult = { exitCode: number; stdout: string; errors: string[] };

function refusal(answer: IoMappingResponse, canonical: boolean): string[] {
  if (answer.status === "missing") {
    return ['No io.json in this folder: run "pantin io init <folder>" first.'];
  }
  return [
    "The mapping is invalid, so no GVL is generated:",
    ...answer.problems.map(describeIoProblem),
    ...(canonical ? [] : [CANONICAL_ORDER_NOTE]),
  ];
}

export async function generateGvl(folder: string): Promise<GvlResult> {
  const read = await readFolderDocument(folder);
  if ("problems" in read) {
    return { exitCode: 1, stdout: "", errors: read.problems };
  }
  const { answer, canonical } = await readFolderIo(folder, read.document);
  if (answer.status !== "valid") {
    return { exitCode: 1, stdout: "", errors: refusal(answer, canonical) };
  }
  const errors =
    answer.unmappedTags.length === 0
      ? []
      : [`note: ${answer.unmappedTags.length} tag(s) are not mapped and not in the GVL.`];
  return { exitCode: 0, stdout: renderGvl(answer.modules), errors };
}
